import{_ as r,c as e,o as l,ae as p}from"./chunks/framework.C-JRAr_X.js";const n="/NEWTEST/assets/7._%EB%AF%BC%EC%9B%90_%EC%9D%91%EB%8C%80_%EB%A7%A4%EB%89%B4%EC%96%BC-image1.BbYEtsws.png",a="/NEWTEST/assets/7._%EB%AF%BC%EC%9B%90_%EC%9D%91%EB%8C%80_%EB%A7%A4%EB%89%B4%EC%96%BC-image2.DhXIEGNX.png",s="/NEWTEST/assets/7._%EB%AF%BC%EC%9B%90_%EC%9D%91%EB%8C%80_%EB%A7%A4%EB%89%B4%EC%96%BC-image3.2ymmdPF2.png",o="/NEWTEST/assets/7._%EB%AF%BC%EC%9B%90_%EC%9D%91%EB%8C%80_%EB%A7%A4%EB%89%B4%EC%96%BC-image4.BCie1K9a.jpeg",d="/NEWTEST/assets/7._%EB%AF%BC%EC%9B%90_%EC%9D%91%EB%8C%80_%EB%A7%A4%EB%89%B4%EC%96%BC-image5.CX7BwKO1.jpeg",i="/NEWTEST/assets/7._%EB%AF%BC%EC%9B%90_%EC%9D%91%EB%8C%80_%EB%A7%A4%EB%89%B4%EC%96%BC-image6.DY8FZoCb.jpeg",m=JSON.parse('{"title":"7. 민원 응대 매뉴얼","description":"","frontmatter":{"title":"7. 민원 응대 매뉴얼"},"headers":[],"relativePath":"manual/7._민원_응대_매뉴얼.md","filePath":"manual/7._민원_응대_매뉴얼.md"}'),g={name:"manual/7._민원_응대_매뉴얼.md"};function h(c,t,u,y,x,b){return l(),e("div",null,t[0]||(t[0]=[p('<p>본 매뉴얼은 서울문화재단 직원이 민원 응대 시 참고할 수 있도록 만든 가이드 라인입니다.</p><p>현장에서 다양한 응대 상황이 발생할 수 있으므로 각 부서에서는 해당 내용을 상황에 맞게 적절히 활용하시되, 특이민원에 대해서는 경영기획팀에 문의 혹은 공유주시면 더욱 원활한 대응이 가능합니다!</p><p>[참고문서]</p><ol><li><p>[행정안전부] 공직자 민원응대 매뉴얼</p></li><li><p>[행정안전부] 악성민원 방지 및 민원공무원 보호 강화 대책</p></li><li><p>[서울시] 특이민원 응대 매뉴얼</p></li><li><p>[서울시] 서울시응답소 응대 매뉴얼</p></li><li><p>[서울문화재단] 서울문화재단 감정노동 보호 매뉴얼</p></li></ol><h1 id="목-차" tabindex="-1">목 차 <a class="header-anchor" href="#목-차" aria-label="Permalink to &quot;목 차&quot;">​</a></h1><table tabindex="0"><thead><tr><th><strong>Ⅰ. 민원이란?</strong></th><th></th><th style="text-align:right;"><a href="#_bookmark0"><strong>03p</strong></a></th></tr></thead><tbody><tr><td><strong>Ⅱ. 민원응대</strong></td><td><strong>기본원칙</strong></td><td style="text-align:right;"><a href="#_bookmark1"><strong>04p</strong></a></td></tr><tr><td><strong>Ⅲ. 일반민원</strong></td><td><strong>응대요령</strong></td><td style="text-align:right;"><a href="#_bookmark2"><strong>05p</strong></a></td></tr><tr><td><strong>Ⅳ. 특이민원</strong></td><td><strong>응대요령</strong></td><td style="text-align:right;"><a href="#반복-전화"><strong>18p</strong></a></td></tr></tbody></table><h2 id="참고-민원-보고서-양식-24p" tabindex="-1">[참고] 민원 보고서 양식 <a href="#참고-민원-보고서-양식">24p</a> <a class="header-anchor" href="#참고-민원-보고서-양식-24p" aria-label="Permalink to &quot;\\[참고\\] 민원 보고서 양식 [24p](#참고-민원-보고서-양식)&quot;">​</a></h2><ol><li><strong>민원이란?</strong></li></ol><h3 id="민-원" tabindex="-1">민 원 <a class="header-anchor" href="#민-원" aria-label="Permalink to &quot;민 원&quot;">​</a></h3><p>국민이 행정기관에 대하여 허가·인가 등의 신청, 행정업무에 대한 상담, 운영 개선 및 고충사항에 대한 처리 등을 요구하는 것으로,</p><p>국민은 행정기관에 대해 문서 또는 구술, 전화, 우편, 인터넷 등으로 민원을 <span id="_bookmark0" class="anchor"></span>제기할 수 있습니다.</p><h3 id="민원인" tabindex="-1">민원인 <a class="header-anchor" href="#민원인" aria-label="Permalink to &quot;민원인&quot;">​</a></h3><p>행정기관에 민원을 제기하는 개인·법인 또는 단체를 말합니다.</p><table style="width:100%;"><colgroup><col style="width:33%;"><col style="width:33%;"><col style="width:33%;"></colgroup><thead><tr><th colspan="3" style="text-align:center;"><p><strong>누구나 민원을 제기할 수 있다!</strong></p></th></tr></thead><tbody><tr><td><p><img src="'+n+'" style="width:1.97894in;height:1.2825in;"></p></td><td><p><img src="'+a+'" style="width:2.1208in;height:1.4125in;"></p></td><td><p><img src="'+s+'" style="width:2.00316in;height:1.33417in;"></p></td></tr><tr><td style="text-align:center;"><p>시 민</p></td><td><p>예술가/단체</p></td><td style="text-align:center;"><p>전문가</p></td></tr></tbody></table><p>아래의 경우, 민원인이 아닙니다.</p><ol><li><p>행정기관, 행정기관과 사법상 계약관계에 있는 자</p></li><li><p>성명·주소 등이 불명확한 자 법인/단체는 명칭, 소재지, 대표자의 성명</p></li></ol><p>우리 재단의 경우, 문서·우편·인터넷 등을 통한 민원의 대부분은</p><ol><li><p><u>서울문화재단 홈페이지 &lt;1:1 문의하기&gt;</u></p></li><li><p><u>서울시응답소 시스템과 연계되어 발생</u>됩니다.</p></li></ol><p>두 시스템 모두 민원인의 이름, 주소 등이 명확하게 제시되지만 개인정보법, 민원법 등에 의해 특정한 사유 없이 열람은 불가합니다.</p><h2 id="민원응대-기본원칙" tabindex="-1">민원응대 기본원칙 <a class="header-anchor" href="#민원응대-기본원칙" aria-label="Permalink to &quot;민원응대 기본원칙&quot;">​</a></h2><ul><li><p><strong>접수된 민원은 특별한 사유가 없으면 <u>즉시 처리가 원칙</u></strong></p></li><li><p><strong>민원의 공정하고 적법한 처리를 통해 민원인의 권익을 보호</strong></p></li></ul><p><strong>√ 민원처리 담당자의 의무(「민원처리법」 제4조 제1항)</strong></p><ul><li>민원을 처리하는 담당자는 민원을 신속·공정·친절·적법하게 처리하여야 함</li></ul><p><strong>√ 민원인의 권리와 의무(「민원처리법」 제5조)</strong></p><ul><li><p><span id="_bookmark1" class="anchor"></span>행정기관에 민원을 신청하고 신속·공정·친절·적법한 응답을 받을 권리가 있음</p></li><li><p>민원 처리 담당자의 적법한 민원처리를 위한 요청에 협조하고, 행정기관에 부당한 요구 및 다른 민원인의 민원 처리를 지연시키는 등의 공무를 방해하지 않아야 함</p></li></ul><ul><li><p><strong>민원인의 눈높이에 맞춘 정중하고 정확한 민원 응대</strong></p><ul><li><p>정중한 억양·어투를 사용</p></li><li><p>민원사항에 대해 정확하고 이해하기 쉬운 설명 사용</p></li></ul></li><li><p><strong>일반적인 민원응대와 특이민원은 분리하여 대응</strong> 특이민원·반복민원 등 상식에 부합하지 않은 민원에 대해서는 민원인의 민원서비스 접근이 제한되고 처벌 대상이 될 수 있음</p></li></ul><p><strong>√ 민원 처리 담당자의 의무와 보호(「민원처리법」 제4조)</strong></p><p>- 민원인 등의 폭언·폭행, 목적이 정당하지 않은 반복 민원으로부터 민원 처리 담당자를 보호하기 위해 필요한 조치를 취해야 함</p><h2 id="일반민원-응대요령" tabindex="-1">일반민원 응대요령 <a class="header-anchor" href="#일반민원-응대요령" aria-label="Permalink to &quot;일반민원 응대요령&quot;">​</a></h2><p><strong>민원 유형</strong> ※ 유형별 응대요령은 6~17페이지 참고</p><h4 id="온라인-민원" tabindex="-1">온라인 민원 <a class="header-anchor" href="#온라인-민원" aria-label="Permalink to &quot;온라인 민원&quot;">​</a></h4><p>인터넷 등 서울시·재단에서 제공하는 온라인 서비스를 통해 발생되는 민원</p><h4 id="전화-민원" tabindex="-1">전화 민원 <a class="header-anchor" href="#전화-민원" aria-label="Permalink to &quot;전화 민원&quot;">​</a></h4><p>내선 번호를 통해 담당부서·담당자에게 민원인이 직접 연락하여 발생되는 민원</p><h4 id="대면-민원" tabindex="-1">대면 민원 <a class="header-anchor" href="#대면-민원" aria-label="Permalink to &quot;대면 민원&quot;">​</a></h4><p>직접 방문·행사 등을 통해 민원인이 현장에서 직접 제기하여 발생하는 민원</p><p>※ 전화 및 대면 민원은 감정노동이 발생할 수 있는 응대 상황으로,</p><p><strong>보호 조치에 대해서 인사팀 &lt;서울문화재단 감정노동 보호 매뉴얼&gt;를 함께</strong> <span id="_bookmark2" class="anchor"></span><strong>살펴보시길 권장 드립니다. (공지사항-15513)</strong></p><h3 id="유형별-응대요령-공통사항" tabindex="-1">유형별 응대요령 공통사항 <a class="header-anchor" href="#유형별-응대요령-공통사항" aria-label="Permalink to &quot;유형별 응대요령 공통사항&quot;">​</a></h3><p><strong>√</strong> 정중한 억양 및 어투를 사용하며, 공감하되 무조건적인 “긍정” 응대는 지양</p><p><strong>√</strong> 민원인 문의사항을 집중하여 끝까지 듣고, 민원사항을 정확히 파악</p><p><strong>√</strong> 민원인의 눈높이에 맞춘 정확하고 이해하기 쉬운 설명 진행</p><p><strong>√</strong> 민원인이 제기한 불만 원인을 파악하고, 잘못된 부분은 사과</p><p><strong>√</strong> 민원인에게 민원내용 보완 요구, 처리 진행 및 결과를 통보시 담당자의 소속·성명 및 연락처를 안내</p><p><strong>민원 보고 필수사항</strong> ※ 민원 보고는 사무위임전결에 따름</p><h5 id="민원-경과를-민원-발생-보고서-양식에-따라-부서장-보고-필수-및-경영-기획팀에-공유-권장-주시면-더욱-원활한-민원-응대가-가능합니다" tabindex="-1">민원 경과를 <a href="#_bookmark5"><u>&lt;민원 발생 보고서&gt;</u></a> 양식에 따라 부서장 보고(<u>필수</u>) 및 경영 기획팀에 공유(<u>권장</u>)주시면 더욱 원활한 민원 응대가 가능합니다. <a class="header-anchor" href="#민원-경과를-민원-발생-보고서-양식에-따라-부서장-보고-필수-및-경영-기획팀에-공유-권장-주시면-더욱-원활한-민원-응대가-가능합니다" aria-label="Permalink to &quot;민원 경과를 [&lt;u&gt;\\&lt;민원 발생 보고서\\&gt;&lt;/u&gt;](#_bookmark5) 양식에 따라 부서장 보고(&lt;u&gt;필수&lt;/u&gt;) 및 경영 기획팀에 공유(&lt;u&gt;권장&lt;/u&gt;)주시면 더욱 원활한 민원 응대가 가능합니다.&quot;">​</a></h5><p>* 단순 건의 외, 고충 · 진정 등에 관한 민원은 소속 부서장 및 실장까지 보고</p><p>** 특이민원은 소속 부서장 · 실장 · 본부장까지 보고</p><p>*** 부정보도 예상 건은 자체 처리하더라도 경영기획팀, 홍보마케팅팀에 공유 필요</p><h3 id="온라인-민원-1" tabindex="-1">온라인 민원 <a class="header-anchor" href="#온라인-민원-1" aria-label="Permalink to &quot;온라인 민원&quot;">​</a></h3><ul><li><strong>서울문화재단 홈페이지 &lt;1:1 문의하기&gt;</strong></li></ul><h4 id="◎-개요" tabindex="-1">◎ 개요 <a class="header-anchor" href="#◎-개요" aria-label="Permalink to &quot;◎ 개요&quot;">​</a></h4><ul><li><p>재단 홈페이지 &lt;1:1 문의하기&gt; 게시판을 통해 발생하는 민원</p></li><li><p>홈페이지를 처음 접하는 시민도 이해할 수 있도록 사업유형·공간별 질문 범주로 구분 * 부서별 구분 X</p></li><li><p>민원인은 해당 범주를 지정하여 질문하며,</p></li></ul><p>대부분 사업에 대한 궁금증 및 간단 질문으로 구성됨</p><h4 id="◎-처리절차" tabindex="-1">◎ 처리절차 <a class="header-anchor" href="#◎-처리절차" aria-label="Permalink to &quot;◎ 처리절차&quot;">​</a></h4><p><strong>경영기획팀</strong></p><p><strong>1. 최초 접수</strong></p><p><strong>4. 답변등록 · 민원종료</strong></p><p><strong>⇓</strong></p><p><strong>필요시 재지정 요청 가능</strong></p><p><strong>⇑</strong></p><p><strong>⇒</strong></p><p><strong>3. 답변서 검토</strong></p><p><strong>2. 민원 확인</strong></p><p><strong>담당 부서</strong></p><h4 id="◎-답변방법" tabindex="-1">◎ 답변방법 <a class="header-anchor" href="#◎-답변방법" aria-label="Permalink to &quot;◎ 답변방법&quot;">​</a></h4><ul><li><p>서울문화재단 CMS 로그인</p></li><li><p>게시판 관리 &gt; 서울문화재단(국문) &gt; 새소식 &gt; 1:1 문의하기</p></li><li><p>민원 게시글 확인 → 우측하단 ‘답변하기’를 통해 부서에서 직접 업로드</p></li></ul><p><strong>√ 답변 예시</strong></p><p>안녕하세요, 서울문화재단 00팀입니다. 문의주신 내용은 00으로 파악됩니다.</p><p>이에 대한 답변은 아래와 같습니다. 가. 000</p><p>나. 000</p><p>추가 문의는 000팀 000 담당자(☎02-3290-0000)에게 문의 부탁드리며, 앞으로도 서울문화재단에 많은 관심 부탁드립니다, 감사합니다.</p><p><strong>※ 필수 기재사항</strong></p><p><strong>① 민원 질문에 대한 명확한 답변</strong></p><p><strong>② 담당자의 팀명, 연락처</strong></p><h4 id="◎-유의사항" tabindex="-1">◎ 유의사항 <a class="header-anchor" href="#◎-유의사항" aria-label="Permalink to &quot;◎ 유의사항&quot;">​</a></h4><ul><li><strong>접수일로부터 5일 이내 답변</strong> * 주말, 공휴일 제외</li></ul><p>ex) <u>24.07.17(수) 민원 접수 시 → 24.07.24(수)까지 답변 등록해야함</u></p><ul><li><p>민원인의 착오로 질문유형(카테고리) 설정이 잘못됐을 경우, 경영기획팀에서 질문유형 변경 후 재안내 가능</p></li><li><p>답변 편의를 위해 유선으로 답변했더라도, <u>답변내용 포함하여 기한 내</u> <u>답변 게시글 작성 필수</u></p></li></ul><h4 id="◎-자주-묻는-q-a" tabindex="-1">◎ 자주 묻는 Q&amp;A <a class="header-anchor" href="#◎-자주-묻는-q-a" aria-label="Permalink to &quot;◎ 자주 묻는 Q&amp;A&quot;">​</a></h4><h5 id="q-민원-답변-표준양식이-따로-정해져있나요" tabindex="-1">Q. 민원 답변 표준양식이 따로 정해져있나요? <a class="header-anchor" href="#q-민원-답변-표준양식이-따로-정해져있나요" aria-label="Permalink to &quot;Q. 민원 답변 표준양식이 따로 정해져있나요?&quot;">​</a></h5><p>A. 말투, 억양 등에 대해 필수로 규정하진 않습니다만 아래 2가지는 필수로 지켜주셔야 합니다.</p><p>① 민원 질문에 대한 명확한 답변</p><p>② 담당자의 소속, 성명 및 연락처 밝히기</p><h5 id="q-민원인이-질문유형-카테고리-을-잘못-설정해-답변할-수-없는-내용에-대해-답변하라는-메일이-왔습니다-어떻게-해야-하나요" tabindex="-1">Q. 민원인이 질문유형(카테고리)을 잘못 설정해 답변할 수 없는 내용에 대해 답변하라는 메일이 왔습니다. 어떻게 해야 하나요? <a class="header-anchor" href="#q-민원인이-질문유형-카테고리-을-잘못-설정해-답변할-수-없는-내용에-대해-답변하라는-메일이-왔습니다-어떻게-해야-하나요" aria-label="Permalink to &quot;Q. 민원인이 질문유형(카테고리)을 잘못 설정해 답변할 수 없는 내용에 대해 답변하라는 메일이 왔습니다. 어떻게 해야 하나요?&quot;">​</a></h5><p>A. 민원 발생 시 경영기획팀에서 민원인의 질문유형(카테고리) 설정, 민원 내용 등을 상시 모니터링하고 있습니다.</p><p>민원인이 범주를 잘못 설정했을 경우, 경영기획팀에서 해당 부서에 민원 내용을 별도 전달하고 답변을 달 수 있게 안내드리고 있으니 <u>잘못된 범주 설정에 대한 질문은 답변 안하셔도 됩니다.</u></p><h5 id="q-cms-서버-접속을-위한-아이디와-비밀번호-생성은-어떻게-하나요" tabindex="-1">Q. CMS 서버 접속을 위한 아이디와 비밀번호 생성은 어떻게 하나요? <a class="header-anchor" href="#q-cms-서버-접속을-위한-아이디와-비밀번호-생성은-어떻게-하나요" aria-label="Permalink to &quot;Q. CMS 서버 접속을 위한 아이디와 비밀번호 생성은 어떻게 하나요?&quot;">​</a></h5><p>A. 정보관리팀에서 부서별로 고유 아이디 및 비밀번호를 부여합니다. 8페에지에서 부서별 CMS 아이디를 안내드렸으니, 참고 부탁드립니다. (비밀번호는 정보관리팀에 문의 후 변경 요청)</p><h4 id="참고-1-카테고리별-담당자-목록-24년-상반기-기준" tabindex="-1">[참고 ①] 카테고리별 담당자 목록(24년 상반기 기준) <a class="header-anchor" href="#참고-1-카테고리별-담당자-목록-24년-상반기-기준" aria-label="Permalink to &quot;\\[참고 ①\\] 카테고리별 담당자 목록(24년 상반기 기준)&quot;">​</a></h4><ul><li><p>카테고리별 담당자에게 &lt;1:1 문의하기&gt; 민원 발생 시 안내 메일이 발송됩니다.</p></li><li><p>카테고리별 담당자 변경 필요 시, 경영기획팀으로 문의 바랍니다.</p></li></ul><table tabindex="0"><thead><tr><th style="text-align:center;"><strong>카테고리</strong></th><th style="text-align:center;"><strong>담당자</strong></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>예술지원</strong></td><td style="text-align:center;">배소현, 한혜인, 한민지, 이현지, 서금슬, 최미리</td></tr><tr><td style="text-align:center;"><strong>예술축제</strong></td><td style="text-align:center;">도재형, 장옥영, 김한솔, 최재훈, 박수진, 윤동주</td></tr><tr><td style="text-align:center;"><strong>지역문화</strong></td><td style="text-align:center;">서명구, 양시내</td></tr><tr><td style="text-align:center;"><strong>문화향유</strong></td><td style="text-align:center;">최원희, 박현주, 선걸, 전정우</td></tr><tr><td style="text-align:center;"><strong>서울예술인지원센터</strong></td><td style="text-align:center;">김수연, 고은혜</td></tr><tr><td style="text-align:center;"><strong>청년예술(청년예술청)</strong></td><td style="text-align:center;">강민정, 함수령</td></tr><tr><td style="text-align:center;"><strong>융합예술(문래예술공장)</strong></td><td style="text-align:center;">김희영, 박선영</td></tr><tr><td style="text-align:center;"><strong>대학로극장 쿼드(QUAD)</strong></td><td style="text-align:center;">안미영, 이지은, 김은나, 최영한, 조성현</td></tr><tr><td style="text-align:center;"><strong>서울연극센터</strong></td><td style="text-align:center;">한정희, 송서연</td></tr><tr><td style="text-align:center;"><strong>서울연극창작센터</strong></td><td style="text-align:center;">현의준, 윤다슬</td></tr><tr><td style="text-align:center;"><strong>무대기자재공유센터</strong></td><td style="text-align:center;">임지은, 김유리</td></tr><tr><td style="text-align:center;"><strong>금천예술공장</strong></td><td style="text-align:center;">이헌, 고영명</td></tr><tr><td style="text-align:center;"><strong>신당창작아케이드</strong></td><td style="text-align:center;">최정필, 이고은</td></tr><tr><td style="text-align:center;"><strong>연희문학창작촌</strong></td><td style="text-align:center;">이승주, 이세옥</td></tr><tr><td style="text-align:center;"><strong>서울무용센터</strong></td><td style="text-align:center;">이정훈, 석주희</td></tr><tr><td style="text-align:center;"><strong>서울장애예술창작센터</strong></td><td style="text-align:center;">김유진, 이화정</td></tr><tr><td style="text-align:center;"><strong>노들섬</strong></td><td style="text-align:center;">우상욱, 김지은, 김상원, 황기성</td></tr><tr><td style="text-align:center;"><strong>서울거리예술창작센터</strong></td><td style="text-align:center;">김진호, 우혜인</td></tr><tr><td style="text-align:center;"><strong>예술교육</strong></td><td style="text-align:center;">정경미, 남혜승</td></tr><tr><td style="text-align:center;"><strong>서울문화예술교육센터 용산</strong></td><td style="text-align:center;">이유나, 유민성</td></tr><tr><td style="text-align:center;"><strong>서울문화예술교육센터 양천</strong></td><td style="text-align:center;">이정연, 신소정</td></tr><tr><td style="text-align:center;"><strong>서울문화예술교육센터 강북</strong></td><td style="text-align:center;">윤나영, 이하늘</td></tr><tr><td style="text-align:center;"><strong>서울문화예술교육센터 서초</strong></td><td style="text-align:center;">박상혁</td></tr><tr><td style="text-align:center;"><strong>서울문화예술교육센터 은평</strong></td><td style="text-align:center;">김윤경, 최지원</td></tr><tr><td style="text-align:center;"><strong>문화제휴</strong></td><td style="text-align:center;">강지은, 김성은, 양지현</td></tr><tr><td style="text-align:center;"><strong>국제교류</strong></td><td style="text-align:center;">강지은, 김성은</td></tr><tr><td style="text-align:center;"><strong>홍보</strong></td><td style="text-align:center;">김은지</td></tr><tr><td style="text-align:center;"><strong>인사채용</strong></td><td style="text-align:center;">주자영</td></tr><tr><td style="text-align:center;"><strong>재무회계</strong></td><td style="text-align:center;">전은영, 염혜원, 김영선</td></tr><tr><td style="text-align:center;"><strong>기타</strong></td><td style="text-align:center;">심희경</td></tr></tbody></table><h4 id="참고-2-부서별-cms-아이디-목록-24년-상반기-기준" tabindex="-1">[참고 ②] 부서별 CMS 아이디 목록(24년 상반기 기준) <a class="header-anchor" href="#참고-2-부서별-cms-아이디-목록-24년-상반기-기준" aria-label="Permalink to &quot;\\[참고 ②\\] 부서별 CMS 아이디 목록(24년 상반기 기준)&quot;">​</a></h4><p><u>* 비밀번호는 부서별로 상이하오니 아이디만 참고해주세요!</u></p><table><colgroup><col style="width:11%;"><col style="width:20%;"><col style="width:38%;"><col style="width:29%;"></colgroup><thead><tr><th colspan="3" style="text-align:center;"><p><strong>부서명</strong></p></th><th style="text-align:center;"><p><strong>아이디</strong></p></th></tr></thead><tbody><tr><td colspan="2" rowspan="3" style="text-align:center;"><p><strong>경영본부</strong></p></td><td style="text-align:center;"><p>경영기획팀</p></td><td style="text-align:center;"><p>plan</p></td></tr><tr><td style="text-align:center;"><p>인사팀</p></td><td style="text-align:center;"><p>human</p></td></tr><tr><td style="text-align:center;"><p>재무회계팀</p></td><td style="text-align:center;"><p>wedjat</p></td></tr><tr><td rowspan="3" style="text-align:center;"></td><td rowspan="3" style="text-align:center;"><p>안전관리실</p></td><td style="text-align:center;"><p>시설안전1팀</p></td><td rowspan="2" style="text-align:center;"><p>sfacfm</p></td></tr><tr><td style="text-align:center;"><p>시설안전2팀</p></td></tr><tr><td style="text-align:center;"><p>정보관리팀</p></td><td style="text-align:center;"><p>sfacpr2</p></td></tr><tr><td rowspan="16" style="text-align:center;"><p><strong>예술 창작 본부</strong></p></td><td rowspan="5" style="text-align:center;"><p>예술지원실</p></td><td style="text-align:center;"><p>예술지원정책팀</p></td><td rowspan="3" style="text-align:center;"><p>artsupport</p></td></tr><tr><td style="text-align:center;"><p>예술지원1팀</p></td></tr><tr><td style="text-align:center;"><p>예술지원2팀</p></td></tr><tr><td style="text-align:center;"><p>융합예술팀</p></td><td style="text-align:center;"><p>artech / mullae</p></td></tr><tr><td style="text-align:center;"><p>청년예술팀</p></td><td style="text-align:center;"><p>youth</p></td></tr><tr><td rowspan="6" style="text-align:center;"><p>대학로센터실</p></td><td style="text-align:center;"><p>예술청팀</p></td><td style="text-align:center;"><p>yesulcheong</p></td></tr><tr><td style="text-align:center;"><p>공연기획팀</p></td><td style="text-align:center;"><p>quad</p></td></tr><tr><td style="text-align:center;"><p>무대기술팀</p></td><td style="text-align:center;"><p>stage</p></td></tr><tr><td style="text-align:center;"><p>서울연극창작센터팀</p></td><td style="text-align:center;"><p>stcc2024</p></td></tr><tr><td style="text-align:center;"><p>서울연극센터팀</p></td><td style="text-align:center;"><p>theater</p></td></tr><tr><td style="text-align:center;"><p>무대기자재공유센터</p></td><td style="text-align:center;"><p>restage</p></td></tr><tr><td rowspan="5" style="text-align:center;"><p>창작기반실</p></td><td style="text-align:center;"><p>서울장애예술창작센터</p></td><td style="text-align:center;"><p>jamsil</p></td></tr><tr><td style="text-align:center;"><p>금천예술공장</p></td><td style="text-align:center;"><p>geumcheon</p></td></tr><tr><td style="text-align:center;"><p>신당창작아케이드</p></td><td style="text-align:center;"><p>sindang</p></td></tr><tr><td style="text-align:center;"><p>연희문학창작촌</p></td><td style="text-align:center;"><p>yeonhui / webyeon</p></td></tr><tr><td style="text-align:center;"><p>서울무용센터</p></td><td style="text-align:center;"><p>hongeun</p></td></tr><tr><td rowspan="13" style="text-align:center;"><p><strong>문화 진흥 본부</strong></p></td><td rowspan="4" style="text-align:center;"><p>문화사업실</p></td><td style="text-align:center;"><p>문화향유팀</p></td><td style="text-align:center;"><p>sfac10</p></td></tr><tr><td style="text-align:center;"><p>노들섬운영팀</p></td><td style="text-align:center;"><p>nodeul</p></td></tr><tr><td style="text-align:center;"><p>노들섬사업팀</p></td><td style="text-align:center;"><p>nodeulpp</p></td></tr><tr><td style="text-align:center;"><p>지역문화팀</p></td><td style="text-align:center;"><p>culture</p></td></tr><tr><td rowspan="3" style="text-align:center;"><p>축제기획실</p></td><td style="text-align:center;"><p>축제기획1팀</p></td><td style="text-align:center;"><p>moviemaster</p></td></tr><tr><td style="text-align:center;"><p>축제기획2팀</p></td><td style="text-align:center;"><p>festival2</p></td></tr><tr><td style="text-align:center;"><p>서울거리예술창작센터</p></td><td style="text-align:center;"><p>ssacc</p></td></tr><tr><td rowspan="6" style="text-align:center;"><p>예술교육실</p></td><td style="text-align:center;"><p>예술교육정책팀</p></td><td style="text-align:center;"><p>artedu / esac</p></td></tr><tr><td style="text-align:center;"><p>서울문화예술교육센터 용산팀</p></td><td style="text-align:center;"><p>yongsanedu</p></td></tr><tr><td style="text-align:center;"><p>서울문화예술교육센터 양천팀</p></td><td style="text-align:center;"><p>wsartedu</p></td></tr><tr><td style="text-align:center;"><p>서울문화예술교육센터 강북팀</p></td><td style="text-align:center;"><p>gbartedu</p></td></tr><tr><td style="text-align:center;"><p>서울문화예술교육센터 서초팀</p></td><td style="text-align:center;"><p>smec</p></td></tr><tr><td style="text-align:center;"><p>서울문화예술교육센터 은평팀</p></td><td style="text-align:center;"><p>eunpyeong2024</p></td></tr><tr><td colspan="2" rowspan="3" style="text-align:center;"><p>정책협력실</p></td><td style="text-align:center;"><p>미래전략팀</p></td><td style="text-align:center;"><p>policy</p></td></tr><tr><td style="text-align:center;"><p>제휴협력팀</p></td><td style="text-align:center;"><p>alliance</p></td></tr><tr><td style="text-align:center;"><p>홍보마케팅팀</p></td><td style="text-align:center;"><p>sfacpr</p></td></tr><tr><td colspan="3" style="text-align:center;"><p>윤리경영실</p></td><td style="text-align:center;"><p>audit</p></td></tr></tbody></table><ul><li><strong>서울시응답소</strong> 서울시에서 관리하는 통합 민원 접수 시스템</li></ul><h4 id="◎-개요-1" tabindex="-1">◎ 개요 <a class="header-anchor" href="#◎-개요-1" aria-label="Permalink to &quot;◎ 개요&quot;">​</a></h4><ul><li><p>서울시 응답소를 통해 재단으로 기관 분배된 민원</p></li><li><p>국민신문고, 120다산콜 등에서 발생하는 민원 또한 서울시 응답소 시스템을 통해 일괄 접수 및 관리</p></li></ul><h5 id="서울시-민원답변-표준안에-근거하여-답변내용을-반드시-처리기한-내-작성하며-답변내용은-반드시-내부기안-결재-을-통해-문서-보관" tabindex="-1">서울시 민원답변 표준안에 근거하여 답변내용을 반드시 처리기한 내 작성하며, 답변내용은 반드시 내부기안(결재)을 통해 문서 보관 <a class="header-anchor" href="#서울시-민원답변-표준안에-근거하여-답변내용을-반드시-처리기한-내-작성하며-답변내용은-반드시-내부기안-결재-을-통해-문서-보관" aria-label="Permalink to &quot;서울시 민원답변 표준안에 근거하여 답변내용을 반드시 처리기한 내 작성하며, 답변내용은 반드시 내부기안(결재)을 통해 문서 보관&quot;">​</a></h5><ul><li><u>민원답변 표준안 처리 여부는 분기별 기관 지적사항으로 반드시 이행</u></li></ul><h4 id="◎-민원-종류" tabindex="-1">◎ 민원 종류 <a class="header-anchor" href="#◎-민원-종류" aria-label="Permalink to &quot;◎ 민원 종류&quot;">​</a></h4><p><strong>&lt;민원인&gt; &lt;접수 창구&gt; &lt;응답소 분류&gt; &lt;서울시 예규&gt; &lt;민원처리법&gt;</strong></p><p>다 다</p><p>시민</p><table tabindex="0"><thead><tr><th>서울시응답소 시장 핫라인</th></tr></thead><tbody><tr><td>국민신문고</td></tr><tr><td>120다산콜재단 (전화, 문자)</td></tr></tbody></table><p>다 다</p><p>다</p><p>다</p><p>다</p><p>1 1</p><p>1 1</p><p><strong>일반민원</strong></p><p><strong>현장민원</strong></p><p><strong>직소민원</strong></p><p><strong>고충민원</strong></p><p>현장민원</p><p>일반민원</p><table tabindex="0"><thead><tr><th>질의민원 건의민원</th></tr></thead><tbody><tr><td>고충민원</td></tr><tr><td>기타민원</td></tr></tbody></table><p>1 1</p><p>※ 직소민원 : 서울시 혹은 서울시에서 별도 지정한 기관(부서)가 답변</p><p>※ 현장민원 : 120 다산콜재단 상담사가 처리자 지정</p><h4 id="◎-처리절차-1" tabindex="-1">◎ 처리절차 <a class="header-anchor" href="#◎-처리절차-1" aria-label="Permalink to &quot;◎ 처리절차&quot;">​</a></h4><table><colgroup><col style="width:13%;"><col style="width:1%;"><col style="width:19%;"><col style="width:5%;"><col style="width:29%;"><col style="width:5%;"><col style="width:26%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>서울시응답소</strong></p></th><th></th><th><p><strong>1. 민원등록</strong></p></th><th style="text-align:center;"><p><strong>⇒</strong></p></th><th><p><strong>2. 기관분배</strong></p></th><th></th><th style="text-align:center;"><p><strong>8. 답변등록 · 민원종료</strong></p></th></tr></thead><tbody><tr><td><p><strong>경영기획팀</strong></p></td><td></td><td><p><strong>3. 민원접수 (응답소 홈페이지)</strong></p></td><td><p><strong>⇙</strong></p><p><strong>⇒</strong></p><p><strong>⇙</strong></p></td><td><p><strong>4. 담당부서 분배 (민원 답변기한 관리)</strong></p></td><td></td><td style="text-align:center;"><p>⇑</p><p><strong>※ 담당부서에서 응답소에 답변 직접 등록</strong></p></td></tr><tr><td style="text-align:center;"><p><strong>담당 부서</strong></p></td><td></td><td><p><strong>5. 민원확인</strong></p><p><strong>(응답소 홈페이지)</strong></p></td><td style="text-align:center;"><p><strong>⇒</strong></p></td><td><p><strong>6. 답변서 작성</strong></p><p><strong>※ 민감 이슈 실장/본부장 논의 필요</strong></p></td><td><p><strong>⇒</strong></p></td><td style="text-align:center;"><p><strong>7. 내부결재(사무위임전결)</strong></p><p><strong>경영기획팀, 윤리경영실 참조</strong></p></td></tr></tbody></table><p><strong>◎ 답변방법</strong></p><ul><li><p>질문에 따른 답변내용 내부기안 <u>* 결재라인 사무위임전결 참고</u></p></li><li><p>서울시응답소 최초 로그인 <u>* 서울시응답소 : <a href="https://url.kr/gq4m4D" target="_blank" rel="noreferrer">https://url.kr/gq4m4D</a></u></p></li><li><p>서울시응답소에서 답변 및 민원 종결</p></li></ul><p><strong>√ 서울시응답소 로그인 방법</strong></p><ul><li><p>최초 ID는 경영기획팀에서 생성 후 담당자에게 안내</p></li><li><p>서울시응답소에 접속할 수 있는 PC는 별도 관리해야하므로 컴퓨터 IP 추가 요청 필요 → 신청은 경영기획팀에 별도 문의</p></li><li><p><u>IP 신청은 부서별 대표 컴퓨터 1개만 가능</u></p></li></ul><h5 id="필수-민원답변-표준안" tabindex="-1">[필수] 민원답변 표준안 <a class="header-anchor" href="#필수-민원답변-표준안" aria-label="Permalink to &quot;\\[필수\\] 민원답변 표준안&quot;">​</a></h5><p><strong>※ 서울시응답소는 아래 표준양식을 <u>반드시 지켜 답변</u>해야합니다.</strong></p><table><colgroup><col style="width:5%;"><col style="width:5%;"><col style="width:89%;"></colgroup><thead><tr><th colspan="2"><p>도입부</p></th><th><p>안녕하십니까? 귀하께서 서울시응답소를 통해 신청한 민원(신청번호 1A-16-00)에 대한 검토결과를 다음과 같이 알려드립니다.</p><p>※ 민원인의 성명대신 귀하로 표현하여 개인정보 보호</p><p>※ 민원신청경로 및 민원접수번호를 기재하여 정확한 민원정보를 재확인</p></th></tr></thead><tbody><tr><td rowspan="2"><p>전 개 부</p></td><td><p>요 지</p></td><td><p>귀하의 민원내용은 &quot;○○○&quot;에 관한 것으로 이해(또는 판단)됩니다.</p><p>※ 민원 요지를 기술하여 동문서답, 민원누락 등 부적정 답변 사전 예방</p></td></tr><tr><td><p>답 변</p></td><td><p>귀하의 질의사항에 대해 검토한 의견은 다음과 같습니다. 가.</p><p>나.</p><p><strong>※ 민원답변시 유의사항</strong></p><ul><li><p>민원사항(요청사항 등)에 대해 누락하지 않도록 작성</p></li><li><p>일반인이 이해하기 쉽도록 작성(전문용어 사용 지양 등)</p></li><li><p>성실한 답변 작성(민원인 요청사항에 대해 구체적 해소방안 제시 또는 처리가 불가능한 경우 전반적으로 상세한 기술 및 이해 설득 등)</p></li></ul></td></tr><tr><td colspan="2"><p>종결부</p></td><td style="text-align:left;"><p>귀하의 질문에 만족스러운 답변이 되었기를 바라며, 답변 내용에 대한 추가 설명이 필요한 경우 ○○○팀 홍길동(☏02-0000-0000)에게 연락주 시면 친절히 안내해 드리도록 하겠습니다. 감사합니다.</p><p><strong>※ 반드시 민원처리 담당자의 정보(3가지) 기재 : 부서, 성명(누락주의), 전화번호</strong></p></td></tr></tbody></table><h5 id="참고-★★★-서울시응답소-시스템-답변-방법" tabindex="-1">[참고] ★★★ 서울시응답소 시스템 답변 방법 <a class="header-anchor" href="#참고-★★★-서울시응답소-시스템-답변-방법" aria-label="Permalink to &quot;\\[참고\\] ★★★ 서울시응답소 시스템 답변 방법&quot;">​</a></h5><p>① [처리자 접수 확정]</p><p><img src="'+o+'" style="width:5.68035in;height:0.34in;"><img src="'+d+'" style="width:5.60904in;height:1.1725in;">민원 업무 &gt; 민원 처리(처리자 분배) &gt; 처리자접수확정 &gt; 동의</p><p>② [최종답변 및 민원 종결]</p><p>최종답변 선택 &gt; 동의사항 확인 &gt; 답변내용 입력 &gt; 확정 및 종결</p><ul><li><img src="'+i+'" style="width:5.05792in;height:3.06927in;">중간답변은 최종답변 처리 전, 중간 안내 사항을 민원인에게 회신하는 버튼 으로 되도록 <strong><u>최종답변을 선택하여 답변 진행</u></strong></li></ul><p>③ [만족도조사 및 추가 답변] : 민원인 선택에 따라 추가답변 여부 결정 만족도조사 결과 확인 &gt; 추가답변 선택 &gt; 답변내용 입력 &gt; 확정 및 종결</p><ul><li>만족도조사는 5첨 척도로 매우만족, 만족, 보통, 미흡, 매우미흡으로 민원인 선택</li></ul><p><strong>√ 단, 다음의 경우 담당자의 판단에 따라 미답변 가능</strong></p><p><strong><u>미답변 하시려면 꼭 ‘아니오’ 선택 후 ‘답변저장’ 눌러주세요.</u></strong></p><p><strong>※ 미답변에 대한 결과 처리 필수 진행</strong></p><ul><li><p>민원의 만족도 조사가 ‘매우만족’, ‘만족’, ‘보통’일 경우</p></li><li><p>접수된 민원의 2차 만족도 조사인 경우</p></li></ul><h5 id="◎-유의사항-1" tabindex="-1">◎ 유의사항 <a class="header-anchor" href="#◎-유의사항-1" aria-label="Permalink to &quot;◎ 유의사항&quot;">​</a></h5><ul><li><p>처리기한 및 민원 답변 표준안 양식 반드시 준수하여 답변</p><ul><li><strong>일반민원 5일, 국민신문고 7일 내 / 주말·공휴일 제외</strong></li></ul></li><li><p>답변자 신원(전화번호 등)을 공개해야하는 응답소 민원 특성 상, 추가적으로 지속 대응해야할 수도 있음</p></li></ul><h4 id="◎-자주-묻는-q-a-1" tabindex="-1">◎ 자주 묻는 Q&amp;A <a class="header-anchor" href="#◎-자주-묻는-q-a-1" aria-label="Permalink to &quot;◎ 자주 묻는 Q&amp;A&quot;">​</a></h4><h5 id="q-담당자-성명-전화번호-공개-등-민원-답변-표준양식을-꼭-지켜야하나요" tabindex="-1">Q. 담당자 성명/전화번호 공개 등 민원 답변 표준양식을 꼭 지켜야하나요? <a class="header-anchor" href="#q-담당자-성명-전화번호-공개-등-민원-답변-표준양식을-꼭-지켜야하나요" aria-label="Permalink to &quot;Q. 담당자 성명/전화번호 공개 등 민원 답변 표준양식을 꼭 지켜야하나요?&quot;">​</a></h5><p>A. <u>네, 필수로 지켜야 합니다.</u></p><p>서울시응답소는 서울시에서 관리하는 통합 민원접수 시스템으로, 답변 내용을 서울시에서 지속적으로 모니터링 합니다.</p><p>또한 접수 절차가 민원인에게 통보되고, 답변누락, 지연율 등이 기관 평가와 연관됨으로 반드시 민원 답변 표준양식을 지켜주시길 바랍니다.</p><h5 id="q-답변-내용을-공문으로-꼭-남겨야하는-이유는-무엇인가요" tabindex="-1">Q. 답변 내용을 공문으로 꼭 남겨야하는 이유는 무엇인가요? <a class="header-anchor" href="#q-답변-내용을-공문으로-꼭-남겨야하는-이유는-무엇인가요" aria-label="Permalink to &quot;Q. 답변 내용을 공문으로 꼭 남겨야하는 이유는 무엇인가요?&quot;">​</a></h5><p>A. 민원 처리에 대한 공식적인 과정을 남겨두기 위함입니다. 서울시응답소를 통하는 민원은 경영기획팀에서 관리하고 윤리경영실 에서 분기별로 모니터링하지만, <u>답변 부서는 담당자 변경, 업무 이관</u> <u>등이 발생했을 때 서울시응답소 민원 내용/답변을 공문 외의 방법으로</u><u>확인하기 어려우므로</u> 내부 결재를 진행하도록 안내드립니다.</p><p>특히 해당 민원이 특이민원으로 이행될 경우, 민원 대응 과정에서 내부 결재문서를 공신력을 높일 수 있는 과정으로 활용될 수 있으니 사무위임 전결 내규에 따라 내부 결재를 진행해주시길 바랍니다.</p><h5 id="q-부서에서-답변할-수-없는-내용을-배분받았습니다-어떻게-해야-할까요" tabindex="-1">Q. 부서에서 답변할 수 없는 내용을 배분받았습니다, 어떻게 해야 할까요? <a class="header-anchor" href="#q-부서에서-답변할-수-없는-내용을-배분받았습니다-어떻게-해야-할까요" aria-label="Permalink to &quot;Q. 부서에서 답변할 수 없는 내용을 배분받았습니다, 어떻게 해야 할까요?&quot;">​</a></h5><p>A. 경영기획팀에서 해당 민원의 요지 파악 후 부서에 분배하지만 내용에 따라 재분배를 해야할 수도 있습니다. 경영기획팀에 변경 연락 주세요!</p><h5 id="q-서울시응답소에-등록된-3회-이상-반복민원은-어떻게-처리하나요" tabindex="-1">Q. 서울시응답소에 등록된 3회 이상 반복민원은 어떻게 처리하나요? <a class="header-anchor" href="#q-서울시응답소에-등록된-3회-이상-반복민원은-어떻게-처리하나요" aria-label="Permalink to &quot;Q. 서울시응답소에 등록된 3회 이상 반복민원은 어떻게 처리하나요?&quot;">​</a></h5><p>A. 3회 이상의 반복민원은 별도 답변처리 없이 민원 종결이 가능합니다. 시스템 상 반복민원 처리 방법은 서울시응답소 시스템 매뉴얼을 참고 부탁드립니다. ※ 이 경우 특이민원이므로 다음 목차의 특이민원 대응 참고</p><h3 id="오프라인-민원" tabindex="-1">오프라인 민원 <a class="header-anchor" href="#오프라인-민원" aria-label="Permalink to &quot;오프라인 민원&quot;">​</a></h3><ul><li><strong>전화 민원</strong></li></ul><h4 id="◎-개요-2" tabindex="-1">◎ 개요 <a class="header-anchor" href="#◎-개요-2" aria-label="Permalink to &quot;◎ 개요&quot;">​</a></h4><ul><li><p>각 담당자에게 유선으로 직접 연락 오는 민원</p></li><li><p>민원인 ↔ 담당자 간 직접적으로 소통하는 방법 중 하나</p></li><li><p>민원인의 의사표시를 문서로 증명할 필요가 없어 대중적으로 쓰이는 민원요청법</p></li></ul><h4 id="◎-처리-절차" tabindex="-1">◎ 처리 절차 <a class="header-anchor" href="#◎-처리-절차" aria-label="Permalink to &quot;◎ 처리 절차&quot;">​</a></h4><p>- 정확한 발음으로 알기 쉽고 정중한 표현 사용하기</p><p><strong>맞이하기</strong></p><p><strong>“안녕하세요, 000팀 000입니다.”</strong></p><p><strong>“늦게 받아서 죄송합니다, 안녕하세요. 000팀 000입니다.”</strong></p><p><strong>⇓</strong></p><p><strong>상담하기</strong></p><p>- 민원인의 요구사항 확인 후 처리 결과 등을 이해하기 쉽게 설명</p><p><strong>“네~ ○○말씀이세요? 제가 바로 처리해 드리겠습니다.”</strong></p><p><strong>“방금 목소리가 잘 들리지 않았습니다. 다시 말씀 부탁드립니다.”</strong></p><p><strong>⇓</strong></p><p>- 추가 요청사항 확인 후 통화 종결</p><p><strong>종결하기</strong></p><p><strong>“더 궁금하신 사항은 없으십니까?”</strong></p><p><strong>“감사합니다. 또 도움드릴 사항이 있으면 편히 연락주세요”</strong></p><p><strong>◎ 답변 방법</strong> <u>* 서울시 민원응대 서비스 점검표 참고</u></p><table><colgroup><col style="width:5%;"><col style="width:11%;"><col style="width:18%;"><col style="width:64%;"></colgroup><thead><tr><th colspan="2"><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>유 형</strong></p></th><th style="text-align:center;"><p><strong>조치 내용</strong></p></th></tr></thead><tbody><tr><td rowspan="4"><p><strong>맞 이 하 기</strong></p></td><td rowspan="2"><p><strong>맞이 태도</strong></p></td><td style="text-align:center;"><p>접속 신속성</p></td><td><p>전화벨이 3회 이내 수신되기 전 응대</p><p>* 4회 이상 전화벨이 울린 후 응대시 양해 인사</p></td></tr><tr><td style="text-align:center;"><p>맞이 인사</p></td><td><p>인사말, 소속, 이름을 모두 밝혀야 함</p></td></tr><tr><td rowspan="2"><p><strong>연결 태도</strong></p></td><td style="text-align:center;"><p>담당자 연결</p></td><td><p>담당자 이름과 전화번호 안내 후 연결</p></td></tr><tr><td style="text-align:center;"><p>본인 소개</p></td><td><p>본인이 담당자임을 밝히고 문의사항 답변</p></td></tr></tbody></table><table><colgroup><col style="width:5%;"><col style="width:11%;"><col style="width:18%;"><col style="width:64%;"></colgroup><thead><tr><th colspan="2"><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>유 형</strong></p></th><th style="text-align:center;"><p><strong>조치 내용</strong></p></th></tr></thead><tbody><tr><td rowspan="4"><p><strong>상 담 하 기</strong></p></td><td rowspan="4"><p><strong>상담 태도</strong></p></td><td style="text-align:center;"><p>언어 표현</p></td><td><p>응대 시 또박또박 명확한 목소리로 응대</p></td></tr><tr><td style="text-align:center;"><p>경청 태도</p></td><td><p>민원인의 말을 끝까지 듣고 공감 표현 후 응대</p></td></tr><tr><td style="text-align:center;"><p>적극적 안내</p></td><td><p>문의사항에 대한 충분한 안내 외 부가적 사항 안내</p></td></tr><tr><td style="text-align:center;"><p>공손한 어투</p></td><td><p>공손하고 정중한 어투로 응대</p></td></tr><tr><td rowspan="2" style="text-align:left;"><p><strong>종 결 하 기</strong></p></td><td rowspan="2"><p><strong>종결 태도</strong></p></td><td style="text-align:center;"><p>종료인사</p></td><td><p>추가문의여부 확인 및 종료인사</p></td></tr><tr><td style="text-align:center;"><p>종료속도</p></td><td><p>민원인보다 늦게 끊음</p></td></tr></tbody></table><h4 id="◎-유의사항-2" tabindex="-1">◎ 유의사항 <a class="header-anchor" href="#◎-유의사항-2" aria-label="Permalink to &quot;◎ 유의사항&quot;">​</a></h4><ul><li>민원 응대시 민원인을 배려 표현 사용</li></ul><p><strong>√ 답변 예시</strong></p><ul><li><p>모르겠는데요 → 죄송하지만 한번 확인 후 다시 연락드려도 될까요?</p></li><li><p>예? 뭐라고요? → 다시 한 번 말씀해 주시겠습니다?</p></li><li><p>잠시만요 → 잠시만 기다려 주십시오.</p><ul><li>민원인이 전화로 폭언·욕설·업무 외 대화 등을 이어나갈 땐, 아래의 방법으로 대응 가능 <strong>이 경우 특이민원이므로 p.21 참고</strong></li></ul></li></ul><p>① 통화내용 녹음 고지 후 녹음</p><p>② 통화 곤란 안내 및 법적조치 후 통화 종료</p><p>③ 지속적인 민원 시, 법적 조치 가능(고소, 경찰 신고 등)</p><h3 id="대면-민원-1" tabindex="-1">대면 민원 <a class="header-anchor" href="#대면-민원-1" aria-label="Permalink to &quot;대면 민원&quot;">​</a></h3><h4 id="◎-개요-3" tabindex="-1">◎ 개요 <a class="header-anchor" href="#◎-개요-3" aria-label="Permalink to &quot;◎ 개요&quot;">​</a></h4><ul><li><p>민원인이 현장에서 직접 제기하는 민원</p></li><li><p>민원인과 담당자가 직접 만나 민원을 직접 전달하고 응대하는 방식</p></li><li><p>현장에서 처리가능한 장점이 있으나 <u>혹시 모를 상황에 대비해 직접</u><u>대응에 대한 절차 숙지 필수</u></p></li></ul><h4 id="◎-처리절차-2" tabindex="-1">◎ 처리절차 <a class="header-anchor" href="#◎-처리절차-2" aria-label="Permalink to &quot;◎ 처리절차&quot;">​</a></h4><ul><li>정중하게 눈을 맞추며 상황에 맞는 인사말로 맞이</li></ul><p><strong>맞이하기</strong></p><ul><li><p>방문목적 확인 및 담당자 안내, 호출</p></li><li><p>시민이 기다릴 경우, 양해를 구하고 좌석 안내</p></li></ul><p><strong>“안녕하세요, 000팀 000입니다.”</strong></p><p><strong>“기다리게 해서 죄송합니다, 000팀 000입니다.”</strong></p><p><strong>⇓</strong></p><ul><li>민원인의 요구사항 확인 후 처리 결과 등을 이해하기 쉽게 설명</li></ul><p><strong>상담하기</strong></p><p><strong>“네~ 00말씀이세요? 제가 바로 처리해 드리겠습니다.” “5분 정도 걸릴 것 같습니다. 빨리 처리해드리겠습니다.” “담당자분과 협의해서 00까지 연락드리겠습니다.”</strong></p><p><strong>“말씀하신 업무가 가능한 부서를 안내드려도 될까요?”</strong></p><p><strong>⇓</strong></p><ul><li>민원 처리 후 인사 및 대면 종결</li></ul><p><strong>배웅하기</strong></p><p><strong>“기다려 주셔서 감사합니다.</strong></p><p><strong>“더 궁금하신 사항은 없으십니까?”</strong></p><p><strong>“감사합니다. 또 도움드릴 사항이 있으시면 언제든지 연락주세요” “안녕히 가십시오.”</strong></p><p><strong>◎ 답변 방법</strong> <u>* 서울시 민원응대 서비스 점검표 참고</u></p><table><colgroup><col style="width:5%;"><col style="width:11%;"><col style="width:18%;"><col style="width:64%;"></colgroup><thead><tr><th colspan="2"><p><strong>구 분</strong></p></th><th style="text-align:center;"><p><strong>유 형</strong></p></th><th style="text-align:center;"><p><strong>조치 내용</strong></p></th></tr></thead><tbody><tr><td colspan="2"><p><strong>응대 환경</strong></p></td><td style="text-align:center;"><p>장소 환경</p></td><td><p>시민이 방문하는 공간을 늘 깨끗하고 쾌적하게 조성</p></td></tr><tr><td rowspan="4"><p><strong>맞 이 하 기</strong></p></td><td rowspan="4"><p><strong>맞이 태도</strong></p></td><td style="text-align:center;"><p>응모 복장</p></td><td><p>단정한 복장과 용모 유지</p></td></tr><tr><td style="text-align:center;"><p>맞이 인사</p></td><td><p>직원이 인사를 하며 친절하게 맞이함</p></td></tr><tr><td style="text-align:center;"><p>응대 태도</p></td><td><p>직원이 방문목적을 공손히 묻고 안내</p></td></tr><tr><td style="text-align:center;"><p>자리 권유</p></td><td><p>직원이 자리를 권함</p></td></tr><tr><td rowspan="5"><p><strong>상 담 하 기</strong></p></td><td rowspan="5"><p><strong>상담 태도</strong></p></td><td style="text-align:center;"><p>공손한 어투</p></td><td><p>공손하고 정중한 어투로 응대</p></td></tr><tr><td style="text-align:center;"><p>경청 태도</p></td><td><p>민원인의 말을 끝까지 듣고 공감 표현 후 응대</p></td></tr><tr><td style="text-align:center;"><p>적극적 안내</p></td><td><p>문의사항에 대한 충분한 안내 외 부가적 사항 안내</p></td></tr><tr><td style="text-align:center;"><p>자료 전달</p></td><td><p>민원인에게 명함, 전화번호 등에 대해 건네줌</p></td></tr><tr><td style="text-align:center;"><p>상담 태도</p></td><td><p>민원인이 원하는 시간만큼 충분히 상담</p></td></tr><tr><td colspan="2"><p><strong>배웅하기</strong></p></td><td style="text-align:center;"><p>종료인사</p></td><td><p>추가문의여부 확인 및 종료인사</p></td></tr></tbody></table><h4 id="◎-유의사항-3" tabindex="-1">◎ 유의사항 <a class="header-anchor" href="#◎-유의사항-3" aria-label="Permalink to &quot;◎ 유의사항&quot;">​</a></h4><ul><li><p>민원 응대시 민원인을 배려 표현 사용</p></li><li><p>민원인이 대면으로 폭언·욕설·업무 외 대화 등을 이어나갈 땐, 아래와 같은 방법으로 대응 가능 <strong>이 경우 특이민원이므로 p.21 참고</strong></p></li></ul><p>① 대화내용 녹음 고지 후 녹음</p><p>② 지속적인 민원 시, 법적 조치 가능(고소, 현장 경찰 신고 등)</p><ol start="4"><li><strong>특이민원 응대요령</strong> <u>※ 인사팀 「감정노동 보호 매뉴얼 참고」</u></li></ol><h3 id="특이민원이란" tabindex="-1">특이민원이란? <a class="header-anchor" href="#특이민원이란" aria-label="Permalink to &quot;특이민원이란?&quot;">​</a></h3><p>폭언, 폭행, 기물파손, 장시간·반복 전화를 동반한 악성민원과</p><p>하소연, 억지주장 등 업무수행에 방해되는 행위를 하는 모든 범주를 특이민원이라 함</p><h3 id="특이민원-유형" tabindex="-1">특이민원 유형 <a class="header-anchor" href="#특이민원-유형" aria-label="Permalink to &quot;특이민원 유형&quot;">​</a></h3><h4 id="폭언" tabindex="-1">폭언 <a class="header-anchor" href="#폭언" aria-label="Permalink to &quot;폭언&quot;">​</a></h4><p>성희롱·외모·신체·가족비하·인격모독·상해협박·직접 욕설·혼잣말 욕설 등</p><h4 id="폭행" tabindex="-1">폭행 <a class="header-anchor" href="#폭행" aria-label="Permalink to &quot;폭행&quot;">​</a></h4><p>폭력·기물파손·주변 민원인 위협·흉기, 인화물 등 위험물 소지</p><h4 id="장시간-전화" tabindex="-1">장시간 전화 <a class="header-anchor" href="#장시간-전화" aria-label="Permalink to &quot;장시간 전화&quot;">​</a></h4><p>정당한 사유 없이 장시간 통화로 다른 민원 처리를 지연</p><h4 id="반복-전화" tabindex="-1">반복 전화 <a class="header-anchor" href="#반복-전화" aria-label="Permalink to &quot;반복 전화&quot;">​</a></h4><p>통화로 정당한 행정처분에 불복하며 동일내용의 민원을 3회 이상 반복</p><h3 id="유형별-응대요령-공통사항-1" tabindex="-1">유형별 응대요령 공통사항 <a class="header-anchor" href="#유형별-응대요령-공통사항-1" aria-label="Permalink to &quot;유형별 응대요령 공통사항&quot;">​</a></h3><p>√ 침착하고, 정중한 민원응대 유지</p><p>√ 법령 및 규정에 근거한 원칙에 따른 대응</p><p><strong>√ <u>위법행위 등에 대한 구체적인 입증을 위한 증거자료 확보</u></strong></p><p>ex) 통화 녹음, 현장 동영상 촬영, 특이민원 발생 보고서 등</p><p><strong>특이민원 보고 필수사항</strong> ※ 민원 보고는 사무위임전결에 따름</p><p><strong>특이민원 발생 경과를 <a href="#_bookmark5"><u>&lt;특이민원 발생 보고서&gt;</u></a> 양식에 따라 소속 부서장 · 실장 · 본부장 및 경영기획팀에 공유주시면 더욱 원활한 민원 응대가 가능합니다.</strong></p><h3 id="대응-체계도" tabindex="-1">대응 체계도 <a class="header-anchor" href="#대응-체계도" aria-label="Permalink to &quot;대응 체계도&quot;">​</a></h3><table><colgroup><col style="width:24%;"><col style="width:75%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>진행단계</strong></p></th><th style="text-align:center;"><p><strong>대응방법</strong></p></th></tr></thead><tbody><tr><td><p><strong>특이민원 발생</strong></p></td><td><ul><li><p>민원인에게 진정 요청 후 녹음고지/동영상 촬영 실시</p></li><li><p>(폭언 등 특이사항 중지 시) 정상 응대 진행</p></li></ul></td></tr></tbody></table><p><strong>⇓</strong></p><p>· 민원응대 곤란 안내 및 법적조치 경고</p><p><strong>특이민원 지속</strong></p><p><strong>⇓</strong></p><p>[담당자] 담당자는 해당 팀 부서장에게 즉각 보고 [부서장] 사안의 경중 판단 후 후속조치 진행여부 결정</p><p><strong>부서장 보고</strong></p><p><strong>⇓</strong></p><p><strong>2회 이상 고지했음에도 민원종결 불가 시 즉시 응대 종료</strong></p><p>[담당자] 법적조치 여부 등 대응 실행</p><ul><li><p>전화통화시 : 통화 강제종료 및 법적대응 시행</p></li><li><p>대면응대시 : 퇴거조치 및 경찰 신고 가능</p></li></ul><p>* 단, 신체접촉 절대금지</p><p>[부서장] 특이민원 발생 보고서 작성 및 상위직급자 보고</p><p>[담당자] 특이민원 발생 상황내용 기록 및 관련 증거 확보</p><p>[부서장] 원만한 해결 노력에도 불구하고,</p><p>특이민원 지속 시 대응체계 초기단계 재진행</p><p>(녹음 고지, 법적조치 경고 등)</p><p><strong>후속 조치</strong></p><h3 id="유형별-특이민원-응대방법" tabindex="-1">유형별 특이민원 응대방법 <a class="header-anchor" href="#유형별-특이민원-응대방법" aria-label="Permalink to &quot;유형별 특이민원 응대방법&quot;">​</a></h3><ul><li><strong>온라인 특이민원(홈페이지 1;1 문의하기, 서울시응답소)</strong></li></ul><h4 id="◎-개요-4" tabindex="-1">◎ 개요 <a class="header-anchor" href="#◎-개요-4" aria-label="Permalink to &quot;◎ 개요&quot;">​</a></h4><ul><li><p>동일한 민원인이 3회 이상의 민원을 반복적으로 요구</p></li><li><p>성희롱·욕설·폭언 등으로 정상적인 답변이 불가능한 내용 제기</p></li></ul><h4 id="◎-처리절차-3" tabindex="-1">◎ 처리절차 <a class="header-anchor" href="#◎-처리절차-3" aria-label="Permalink to &quot;◎ 처리절차&quot;">​</a></h4><ul><li>「민원처리에 관한 법률」 제23조에 의거하여 <u>1~2차까지는 처리 결과를</u> <u>통지하고 <strong>3차 이후부터 미답변 가능</strong></u></li></ul><p><strong>⇒ ⇒</strong></p><p>4차</p><p>내부 종결처리</p><p><strong>3차 이후의 민원은 종결됨을 안내</strong></p><p>(하단 답변안 참고)</p><p>1차 · 2차 처리 (<u>일반민원과 동일처리</u>)</p><ul><li><p>단, 성희롱·욕설·폭언 민원은 미답변, 미처리 가능</p></li><li><p>특이민원으로 처리 필요 시, <strong><u>경영기획팀과 사전 상의 후 처리</u></strong></p></li></ul><p><strong>◎ 민원답변 표준안(권고)</strong></p><table><colgroup><col style="width:5%;"><col style="width:5%;"><col style="width:89%;"></colgroup><thead><tr><th colspan="2"><p>도입부</p></th><th><p>안녕하십니까? 귀하께서 국민신문고에 제기하신 민원(접수번호 : 00D)에 대한 검토 결과를 다음과 같이 알려드립니다.</p><p>※ 민원인의 성명대신 귀하로 표현하여 개인정보 보호</p><p>※ 민원신청경로 및 민원접수번호를 기재하여 정확한 민원정보를 재확인</p></th></tr></thead><tbody><tr><td rowspan="2"><p>전 개 부</p></td><td><p>요 지</p></td><td><p>귀하는 &quot;○○○&quot;에 관한 민원을 3번 이상 제기하셨습니다. [1차 접수] 접수번호(00A0W0D0)에 대한 답변 완료</p><p>[2차 접수] 접수번호(00WED000)에 대한 답변 완료 [3차 접수] 접수번호(00BDERT0)에 대한 민원 접수</p></td></tr><tr><td><p>답 변</p></td><td style="text-align:left;"><p>「민원 처리에 관한 법률」 제23조(반복 및 중복민원의 처리)는 민원인이 동일한 내용의 민원을 정당한 사유 없이 3회 이상 반복한 경우에는 2회 이상 그 처리결과를 통지하고, 그 후 접수되는 민원에 대해서는 행정 기관의 장(위임전결규정에따라 위임을 받은 자)이 종결처리 할 수 있 도록 하고 있습니다.</p><p>이에 귀하의 민원의 경우 기 답변을 통해 민원처리 결과를 통지 드린 바 있으나, 재차 민원을 제기하셨기에 불가피하게 관련 법률에 따라 반복민원 으로 자체 종결하게됨을 양해해 주시기 바랍니다.</p></td></tr><tr><td colspan="2"><p>종결부</p></td><td style="text-align:left;"><p>귀하의 질문에 만족스러운 답변이 되었기를 바라며, 답변 내용에 대한 추가 설명이 필요한 경우 ○○○팀 홍길동(☏02-0000-0000)에게 연락 주시면 친절히 안내해 드리도록 하겠습니다. 감사합니다.</p><p><strong>※ 반드시 민원처리 담당자의 정보(3가지) 기재 : 부서, 성명(누락주의), 전화번호</strong></p></td></tr></tbody></table><h3 id="전화-특이민원" tabindex="-1">전화 특이민원 <a class="header-anchor" href="#전화-특이민원" aria-label="Permalink to &quot;전화 특이민원&quot;">​</a></h3><h4 id="◎-개요-5" tabindex="-1">◎ 개요 <a class="header-anchor" href="#◎-개요-5" aria-label="Permalink to &quot;◎ 개요&quot;">​</a></h4><ul><li><p>동일한 답변만 가능한 사항이나 같은 내용의 민원을 반복적으로 요구</p></li><li><p>재단에서 처리할 수 없는 민원(타 기관 소관사항, 정당하지 아니한 민원)</p></li><li><p>성희롱·욕설·고성·혼잣말 등으로 정상적인 상담이 불가능한 경우</p></li></ul><h4 id="◎-처리절차-4" tabindex="-1">◎ 처리절차 <a class="header-anchor" href="#◎-처리절차-4" aria-label="Permalink to &quot;◎ 처리절차&quot;">​</a></h4><ul><li>「민원처리법 시행령」에 의거하여 특이민원이 <strong>최대 권장시간 통화 20분</strong></li></ul><h5 id="도달-시-통화자가-구두로-종료-예고-및-통화-종료" tabindex="-1">도달 시 <u>통화자가 구두로 종료 예고 및 통화 종료</u> <a class="header-anchor" href="#도달-시-통화자가-구두로-종료-예고-및-통화-종료" aria-label="Permalink to &quot;도달 시 &lt;u&gt;통화자가 구두로 종료 예고 및 통화 종료&lt;/u&gt;&quot;">​</a></h5><ul><li><p>단 성희롱 · 욕설 · 폭언시, 통화 종료 안내 후 <u>즉시 종료</u></p></li><li><p>이 경우 소속 부서장 · 실장 · 본부장 보고 및 경영기획팀에 공유</p></li></ul><h4 id="◎-전화-종료-멘트-권고" tabindex="-1">◎ 전화 종료 멘트(권고) <a class="header-anchor" href="#◎-전화-종료-멘트-권고" aria-label="Permalink to &quot;◎ 전화 종료 멘트(권고)&quot;">​</a></h4><ul><li><p>다른 내용이 없으시면 장시간 통화로 인해 통화를 종료할 예정입니다. 양해 바랍니다. → 예고 후에도 반복민원 시 통화 즉시 종료</p></li><li><p>성희롱, 욕설, 폭언으로 인해 통화가 종료됩니다. → 통화 즉시 종료</p></li></ul><h3 id="대면-특이민원" tabindex="-1">대면 특이민원 <a class="header-anchor" href="#대면-특이민원" aria-label="Permalink to &quot;대면 특이민원&quot;">​</a></h3><h4 id="◎-개요-6" tabindex="-1">◎ 개요 <a class="header-anchor" href="#◎-개요-6" aria-label="Permalink to &quot;◎ 개요&quot;">​</a></h4><ul><li><p>동일한 답변만 가능한 사항이나 같은 내용의 민원을 반복적으로 요구</p></li><li><p>흉기 소지 등으로 인해 안전에 우려 있는 경우</p></li><li><p>성희롱, 욕설, 고성, 혼잣말 등으로 정상적인 상담이 불가능한 경우</p></li></ul><h4 id="◎-처리절차-5" tabindex="-1">◎ 처리절차 <a class="header-anchor" href="#◎-처리절차-5" aria-label="Permalink to &quot;◎ 처리절차&quot;">​</a></h4><ul><li><p>「민원처리법 시행령」에 의거하여 특이민원 발생시 <strong>민원 응대 즉시 종료</strong></p></li><li><p>안전에 우려가 있을 경우, 출입 제한, 퇴거 조치 가능 (흉기 소지, 성희롱·욕설·고성 등 포함)</p></li></ul><p>※ <strong>즉시 경찰 신고 등 가능</strong>하며, 신체접촉 절대 금지</p><ul><li>이 경우 소속 부서장 · 실장 · 본부장 보고 및 경영기획팀에 공유</li></ul><h3 id="특이민원-행위-유형-및-적용법률" tabindex="-1">특이민원 행위 유형 및 적용법률 <a class="header-anchor" href="#특이민원-행위-유형-및-적용법률" aria-label="Permalink to &quot;특이민원 행위 유형 및 적용법률&quot;">​</a></h3><table><colgroup><col style="width:5%;"><col style="width:10%;"><col style="width:84%;"></colgroup><thead><tr><th colspan="2"><p><strong>단순폭언</strong></p></th><th><ul><li><p>정당한 이유 없이 시비를 걸거나 거칠게 겁을 주는 말이나 행위</p></li><li><p>「경범죄 처벌법」 제3조 제1항 제19호 : 불안감 조성</p></li><li><p>10만 원 이하의 벌금, 구류 또는 과료의 형으로 처벌</p></li></ul></th></tr></thead><tbody><tr><td colspan="2"><p><strong>모욕</strong></p></td><td><ul><li><p>공연히 사람을 모욕하는 행위</p></li><li><p>「형법」 제311조 : 모욕</p></li><li><p>1년 이하의 징역이나 금고 또는 200만 원 이하 벌금</p></li></ul></td></tr><tr><td colspan="2"><p><strong>협박</strong></p></td><td><ul><li><p>폭언의 내용에 ‘해악의 고지’로써 상대방에게 공포심을 일으킬 정도의 것이 포함되어 있다면 협박죄에 대항</p></li><li><p>「형법」 제136조 : 공무집행방해</p></li><li><p>5년 이하의 징역 또는 1천만원 이하의 벌금</p></li></ul></td></tr><tr><td rowspan="2"><p><strong>전 화 응 대</strong></p></td><td><p><strong>반복 전화</strong></p></td><td><ul><li><p>정당한 이유 없이 전화, 문자, 편지, 전자우편, 전자문서 등을 여러 차례 되풀이 하여 괴롭히는 행위</p></li><li><p>「경범죄 처벌법」 제3조 제1항 제40호 : 장난전화 등</p></li><li><p>10만 원 이하 벌금, 구류 또는 과료</p></li></ul></td></tr><tr><td><p><strong>성희롱</strong></p></td><td><ul><li><p>전화, 우편 등을 이용하여 성적 수치심이나 혐오를 일으키는 행위</p></li><li><p>「성폭력범죄의 처벌 등에 관한 특례법」 제13조 : 통신매체를 이용한 음란행위</p></li><li><p>2년 이하의 징역 또는 2천만 원 이하의 벌금</p></li></ul></td></tr><tr><td colspan="2"><p><strong>업무방해</strong></p></td><td><ul><li><p>허위의 사실을 유포하거나 위계 또는 위력으로써 사람의 업무를 방해하는 행위</p></li><li><p>「형법」 제136조 : 공무집행방해 / 「형법」 제314조 : 업무방해</p></li><li><p>5년 이하의 징역 또는 1천만 원 이하의 벌금</p></li></ul></td></tr><tr><td colspan="2"><p><strong>폭행</strong></p></td><td><ul><li><p>사람의 신체에 유형력을 행사</p></li><li><p>「형법」 제136조 : 공무집행방해</p></li><li><p>5년 이하의 징역, 1천만 원 이하의 벌금</p></li></ul></td></tr></tbody></table><p><strong>※ 민원인·민원 상황 등에 대한 <u>법적 조치는 재단 고문변호사 제도(경영기획팀)를</u> <u>활용하여 법적논의를 진행</u>할 수 있습니다.</strong></p><p><strong>※ 이 경우 발생한 직원의 보호조치는 「감정노동 보호 매뉴얼(인사팀)」을 참고하 시길 바랍니다.</strong></p><p><strong>※ 이외 일반민원, 특이민원 발생으로 민원총괄자와 상의가 필요하실 경우, 경영기획팀으로 편히 연락주십시오.</strong></p><h3 id="참고-고충민원-해소를-위한-「민원-배심제」" tabindex="-1">[참고] 고충민원 해소를 위한 「민원 배심제」 <a class="header-anchor" href="#참고-고충민원-해소를-위한-「민원-배심제」" aria-label="Permalink to &quot;\\[참고\\] 고충민원 해소를 위한 「민원 배심제」&quot;">​</a></h3><h4 id="◎-개요-7" tabindex="-1">◎ 개요 <a class="header-anchor" href="#◎-개요-7" aria-label="Permalink to &quot;◎ 개요&quot;">​</a></h4><ul><li><p>「서울특별시 민원배심제 운영 조례」에 따라 서울시의 업무로 인해 발생한 고충민원을 <u>시민의 의견을 바탕</u>으로 해소하기 위한 제도</p></li><li><p>민원배심제를 통해 민원인과 관련 기관(부서)는 시민과 시민 옴부 즈만으로 구성된 배심원단을 통해 객관적이고 중립적인 판단 가능</p></li></ul><h4 id="◎-신청방법" tabindex="-1">◎ 신청방법 <a class="header-anchor" href="#◎-신청방법" aria-label="Permalink to &quot;◎ 신청방법&quot;">​</a></h4><ul><li><p>신 청 자 : 고충민원 처리부서(민원인도 신청 가능)</p></li><li><p>신청방법 : <strong>경영기획팀을 통해 서울시로 일괄 신청</strong></p></li><li><p>신청대상</p></li></ul><p>① 처리기준이 명확하지 않아 객관적이고 중립적인 제3자 판단이 필요한 민원</p><p>② 법령 미비 등으로 전문적 법률 검토 등이 필요한 고충 민원 등</p><h4 id="◎-배심원단-구성-방법" tabindex="-1">◎ 배심원단 구성 방법 <a class="header-anchor" href="#◎-배심원단-구성-방법" aria-label="Permalink to &quot;◎ 배심원단 구성 방법&quot;">​</a></h4><ul><li><p>구성인원 : 5인 이상 7인 이내(대표배심원 1명 포함)</p></li><li><p>구성방법 : 배심원단 후보단에서 구성하되, 시민감사옴부즈만, 시민 참여옴부즈만, 전문가배심원, 시민배심원 중에서 각각 1~3명씩으로 구성</p></li></ul><p>※ 배심원 후보단(100명): 시민감사옴부즈만(6), 시민참여옴부즈만(50), 전문가배심원(28), 시민배심원(16)</p><p><strong>◎ 운영절차 : 안건선정 → 일정협의 및 통보 → 배심제 → 결정 통보</strong></p><p><strong>◎ 배심결과 : 권고(인용시) 또는 기각(불인용시)</strong></p><h1 id="참고-민원-보고서-양식" tabindex="-1">[참고] 민원 보고서 양식 <a class="header-anchor" href="#참고-민원-보고서-양식" aria-label="Permalink to &quot;\\[참고\\] 민원 보고서 양식&quot;">​</a></h1><p><strong>[서식 1] 서울시 응답소 민원답변 기안문(양식) <u>※ 민원 전문 및 답변 붙임파일 필수</u></strong></p><p><strong>[서식 2] 민원 경과 보고서(양식)</strong></p><p><strong>2024.06.21. 접수 민원에 대한 경과 보고서</strong></p><p><strong>경영본부 경영기획팀 홍길동(☎02-3290-0000)</strong></p><p><strong>최근 서울시응답소 접수된 000 공간 엘리베이터 고장 요청 민원에 대한 진행 경과를 보고드림</strong></p><p><strong>□ [‘24.06.21] 민원 접수</strong></p><ul><li><p>민원 경로 : 서울시응답소(국민신문고, 다산콜) 통한 민원(담당자 : 홍길동 주임)</p></li><li><p>민원 요지 : 00센터 엘리베이터 고장으로 인한 수리 접수 건</p></li></ul><p><strong>&lt;민원 전문&gt;</strong></p><ul><li><p>제목 : 엘리베이터 고장 신고합니다.</p></li><li><p>내용 : 000 공간의 엘리베이터 고장났으니 고쳐주시길 바랍니다.</p></li></ul><p>- 처리기한 : ~‘2407.01(월) 23:59:59</p><p><span id="_bookmark5" class="anchor"></span><strong>□ [‘24.06.28] 민원 답변</strong></p><p>안녕하십니까? 귀하께서 서울시응답소를 통해 신청한 민원(신청번호 1A-16)에 대한 검토결과를 다음과 같이 알려드립니다.</p><p>귀하의 민원내용은 &quot;엘리베이터 고장으로 인한 수리 요청&quot;에 관한 것으로 이해 됩니다.</p><p>귀하의 질의사항에 대해 검토한 의견은 다음과 같습니다.</p><p>6월 21일 “엘리베이터 고장” 신고 접수 후, 6월 22일 오전 중 바로 수리하 였으며 6월 22일 오후부터 엘리베이터 운영을 재개하였습니다.</p><p>귀하의 질문에 만족스러운 답변이 되었기를 바라며, 답변 내용에 대한 추가 설명이 필요한 경우 000팀 홍길동(☏02-0000-0000)에게 연락주시면 친절히 안내해 드리도록 하겠습니다. 감사합니다.</p><p><strong>□ [‘24.06.28] 민원 종결</strong></p><p><strong>[서식 3] 특이민원 발생 보고서(양식)</strong></p><p><strong>특이민원 발생 보고서</strong></p><table><colgroup><col style="width:16%;"><col style="width:10%;"><col style="width:6%;"><col style="width:3%;"><col style="width:10%;"><col style="width:10%;"><col style="width:6%;"><col style="width:1%;"><col style="width:1%;"><col style="width:10%;"><col style="width:3%;"><col style="width:6%;"><col style="width:10%;"></colgroup><thead><tr><th style="text-align:center;"><p><strong>발생일자</strong></p></th><th colspan="2"></th><th colspan="2"><p><strong>부서</strong></p></th><th colspan="3"></th><th colspan="3"><p><strong>부서장</strong></p></th><th colspan="2"></th></tr></thead><tbody><tr><td rowspan="3"><p><strong>특이민원 유형</strong></p></td><td><p><strong>폭언 (욕설 등)</strong></p></td><td colspan="2"><p><strong>협박</strong></p></td><td><p><strong>폭행</strong></p></td><td><p><strong>성희롱</strong></p></td><td colspan="3"><p><strong>기물 파손</strong></p></td><td><p><strong>위험물 소지</strong></p></td><td colspan="2"><p><strong>주취 소란</strong></p></td><td><p><strong>기타 *</strong></p></td></tr><tr><td></td><td colspan="2"></td><td></td><td></td><td colspan="3"></td><td></td><td colspan="2"></td><td></td></tr><tr><td colspan="12"><p>* 기타 : 무고, 허위사실 유포 등으로 체크 후 이 칸에 적어주십시오.</p></td></tr><tr><td style="text-align:center;"><p><strong>민원인</strong></p></td><td colspan="2"></td><td colspan="2"><p><strong>전화번호</strong></p></td><td colspan="8"><p>□ 1회 □ 2회 □ 3회 이상</p></td></tr><tr><td style="text-align:center;"><p><strong>담당자</strong></p></td><td colspan="2"></td><td colspan="2"><p><strong>전화번호</strong></p></td><td colspan="2"></td><td colspan="3"><p><strong>담당업무</strong></p></td><td colspan="3"></td></tr><tr><td><p><strong>특이민원 발생요지</strong></p></td><td colspan="12"><p>※ 6하원칙에 따라 핵심내용 위주로 간략하게 작성</p></td></tr><tr><td><p><strong>담당자 의견</strong></p></td><td colspan="12"></td></tr><tr><td><p><strong>부서장 의견</strong></p></td><td colspan="12"><p>※ 부서장 이상 실장 · 본부장에 따른 의견도 함께 추가하여 작성</p></td></tr><tr><td><p><strong>관련부서 요청사항</strong></p></td><td colspan="12"><p>※ 필요시 작성</p></td></tr></tbody></table>',319)]))}const f=r(g,[["render",h]]);export{m as __pageData,f as default};
